CREATE TABLE IF NOT EXISTS travel_visa_orders(id INTEGER PRIMARY KEY AUTOINCREMENT,tenant_key TEXT NOT NULL,public_ref TEXT NOT NULL UNIQUE,service_code TEXT NOT NULL,customer_user_id INTEGER REFERENCES users(id),amount TEXT NOT NULL,currency TEXT NOT NULL,payment_status TEXT NOT NULL DEFAULT 'pending' CHECK(payment_status IN('pending','paid','refunded')),lifecycle_status TEXT NOT NULL DEFAULT 'awaiting_payment' CHECK(lifecycle_status IN('awaiting_payment','paid','processing','completed','cancelled')),invoice_id TEXT,processing_started_at TEXT,processing_lock TEXT,refund_lock TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_travel_visa_orders_tenant ON travel_visa_orders(tenant_key,lifecycle_status,created_at DESC);
CREATE TABLE IF NOT EXISTS travel_visa_events(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES travel_visa_orders(id) ON DELETE CASCADE,event_type TEXT NOT NULL,actor_ref TEXT NOT NULL DEFAULT '',idempotency_key TEXT NOT NULL DEFAULT '',payload_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(order_id,event_type,idempotency_key));
